# Drum sounds
kick = 36
snare = 38
hihat = 42

# Function to create a gentle drum pattern
def softBeat():
    for beat in range(8):

        # Soft kick on the first and fifth beats
        if beat == 0 or beat == 4:
            playNote(kick, beats=0.5)

        # Gentle snare on beats 3 and 7
        elif beat == 2 or beat == 6:
            playNote(snare, beats=0.5)

        # Light hi-hat on remaining beats
        else:
            playNote(hihat, beats=0.5)

        rest(0.5)

# Repeat the pattern four times
for section in range(4):
    softBeat()
